using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.RegularExpressions;
using PureQL.CSharp.Model.Fields;
using PureQL.CSharp.Model.Keys;
using PureQL.CSharp.Model.Lists;
using PureQL.CSharp.Model.Literals;
using PureQL.CSharp.Model.Parameters;
using PureQL.CSharp.Model.Types;

namespace PureQL.CSharp.Model.Tests;

// Checks every public type of the model against the conventions it is generated by:
// unions hold each case as their value, records keep their constructor arguments,
// nodes declare the type their name says, and every expression union holds exactly the
// expressions of its context whose declared type it accepts.
public sealed partial class ModelShapeTests
{
    private static readonly Type[] ModelTypes =
        typeof(PureQLQuery).Assembly.GetExportedTypes();

    private static readonly Type[] Unions = [.. ModelTypes.Where(IsUnion)];

    private static readonly Type[] Records =
    [
        .. ModelTypes.Where(type => type.IsClass && !type.IsAbstract),
    ];

    private static readonly Type[] TypedInterfaces =
    [
        typeof(IOperator),
        typeof(IField),
        typeof(IParameter),
        typeof(ILiteral),
        typeof(IKey),
        typeof(ISubqueryColumn),
    ];

    private static readonly string[] Contexts = ["Row", "Projection", "Group", "Total"];

    private static readonly string[] TypeNames =
    [
        "integer",
        "decimal",
        "string",
        "boolean",
        "date",
        "time",
        "datetime",
        "uuid",
    ];

    private static bool IsUnion(Type type)
    {
        return type.IsValueType && typeof(IUnion).IsAssignableFrom(type);
    }

    private static Type[] Cases(Type union)
    {
        return
        [
            .. union
                .GetConstructors()
                .Select(c => c.GetParameters().Single().ParameterType),
        ];
    }

    // How many records a sample of each type needs at least, computed to a fixed point:
    // unions sample their lightest case, so building a sample always reaches a leaf.
    private static readonly Dictionary<Type, int> Weights = ComputeWeights();

    private const int Unbuilt = 1_000_000;

    private static Dictionary<Type, int> ComputeWeights()
    {
        Dictionary<Type, int> weights = ModelTypes
            .Where(type => IsUnion(type) || (type.IsClass && !type.IsAbstract))
            .ToDictionary(type => type, _ => Unbuilt);
        bool changed = true;
        while (changed)
        {
            changed = false;
            foreach (Type type in weights.Keys.ToArray())
            {
                int weight = IsUnion(type)
                    ? Cases(type).Min(c => Weight(c, weights))
                    : Math.Min(
                        Unbuilt,
                        1
                            + Constructor(type)
                                .GetParameters()
                                .Sum(p => Weight(p.ParameterType, weights))
                    );
                if (weight < weights[type])
                {
                    weights[type] = weight;
                    changed = true;
                }
            }
        }
        Assert.DoesNotContain(Unbuilt, weights.Values);
        return weights;
    }

    private static int Weight(Type type, Dictionary<Type, int> weights)
    {
        type = Nullable.GetUnderlyingType(type) ?? type;
        return type.IsGenericType
            && type.GetGenericTypeDefinition() == typeof(IEnumerable<>)
            ? Weight(type.GetGenericArguments()[0], weights)
            : weights.GetValueOrDefault(type);
    }

    private static int Weight(Type type)
    {
        return Weight(type, Weights);
    }

    private static ConstructorInfo Constructor(Type record)
    {
        return Assert.Single(record.GetConstructors());
    }

    private static object Sample(Type type)
    {
        Type? nullable = Nullable.GetUnderlyingType(type);
        return nullable is not null
            ? Sample(nullable)
            : type switch
            {
                _ when type == typeof(string) => "name",
                _ when type == typeof(bool) => true,
                _ when type == typeof(long) => 7L,
                _ when type == typeof(decimal) => 1.5m,
                _ when type == typeof(DateOnly) => new DateOnly(2024, 2, 29),
                _ when type == typeof(TimeOnly) => new TimeOnly(23, 59, 59),
                _ when type == typeof(DateTimeOffset) => new DateTimeOffset(
                    2024,
                    2,
                    29,
                    23,
                    59,
                    59,
                    TimeSpan.Zero
                ),
                _ when type == typeof(Guid) => Guid.Parse(
                    "8f2a5c1e-3b7d-4e9a-a1c2-6d4b8e0f2a37"
                ),
                { IsEnum: true } => Enum.GetValues(type).GetValue(1)!,
                { IsGenericType: true }
                    when type.GetGenericTypeDefinition() == typeof(IEnumerable<>) =>
                    SampleArray(type.GetGenericArguments()[0]),
                _ when IsUnion(type) => Wrap(type, Sample(Cases(type).MinBy(Weight)!)),
                _ => Construct(Constructor(type)),
            };
    }

    private static Array SampleArray(Type element)
    {
        Array array = Array.CreateInstance(element, 1);
        array.SetValue(Sample(element), 0);
        return array;
    }

    private static object Construct(ConstructorInfo constructor)
    {
        return constructor.Invoke([
            .. constructor.GetParameters().Select(p => Sample(p.ParameterType)),
        ]);
    }

    private static object Wrap(Type union, object value)
    {
        return union.GetConstructor([value.GetType()])!.Invoke([value]);
    }

    private static string Declared(Type node)
    {
        IType type = (IType)node.GetProperty("Type")!.GetValue(Sample(node))!;
        return type.Name + (type.Nullable ? "?" : "");
    }

    [Fact]
    public void EveryTypeIsARecordAUnionAnInterfaceOrAnEnum()
    {
        foreach (Type type in ModelTypes)
        {
            bool isRecord =
                type.IsClass && type.IsSealed && type.GetMethod("<Clone>$") is not null;
            Assert.True(
                isRecord || IsUnion(type) || type.IsInterface || type.IsEnum,
                $"{type.Name} is not a sealed record, a union, an interface or an enum"
            );
        }
    }

    [Fact]
    public void UnionsHoldEachCaseAsTheirValue()
    {
        Assert.NotEmpty(Unions);
        foreach (Type union in Unions)
        {
            Type[] cases = Cases(union);
            Assert.Equal(cases.Length, cases.Distinct().Count());
            Assert.All(
                cases,
                c => Assert.False(IsUnion(c), $"{union.Name} nests {c.Name}")
            );
            foreach (Type caseType in cases)
            {
                object value = Sample(caseType);
                IUnion instance = (IUnion)Wrap(union, value);
                Assert.Equal(value, instance.Value);
                if (!caseType.IsValueType)
                {
                    Assert.Same(value, instance.Value);
                }
            }
        }
    }

    [Fact]
    public void RecordsKeepTheirConstructorArguments()
    {
        Assert.NotEmpty(Records);
        foreach (Type record in Records)
        {
            ConstructorInfo constructor = Constructor(record);
            ParameterInfo[] parameters = constructor.GetParameters();
            object[] arguments = [.. parameters.Select(p => Sample(p.ParameterType))];
            object instance = constructor.Invoke(arguments);
            for (int i = 0; i < parameters.Length; i++)
            {
                PropertyInfo? property = record.GetProperty(
                    parameters[i].Name!,
                    BindingFlags.Public | BindingFlags.Instance | BindingFlags.IgnoreCase
                );
                Assert.True(
                    property is not null,
                    $"{record.Name} has no property for {parameters[i].Name}"
                );
                Assert.Equal(arguments[i], property.GetValue(instance));
            }
        }
    }

    [Fact]
    public void OptionalPropertiesDefaultToAbsent()
    {
        foreach (Type record in Records)
        {
            ConstructorInfo constructor = Constructor(record);
            ParameterInfo[] parameters = constructor.GetParameters();
            object? instance = constructor.Invoke(
                BindingFlags.OptionalParamBinding,
                null,
                [
                    .. parameters.Select(p =>
                        p.IsOptional ? Type.Missing : Sample(p.ParameterType)
                    ),
                ],
                null
            );
            foreach (ParameterInfo parameter in parameters.Where(p => p.IsOptional))
            {
                object? value = record
                    .GetProperty(
                        parameter.Name!,
                        BindingFlags.Public
                            | BindingFlags.Instance
                            | BindingFlags.IgnoreCase
                    )!
                    .GetValue(instance);
                // An absent enum property is its first member: `asc`, `group`.
                Assert.Equal(
                    parameter.ParameterType.IsEnum
                        ? Enum.GetValues(parameter.ParameterType).GetValue(0)
                        : null,
                    value
                );
            }
            // Required parameters come first.
            Assert.True(
                parameters.SkipWhile(p => !p.IsOptional).All(p => p.IsOptional),
                $"{record.Name} has a required parameter after an optional one"
            );
        }
    }

    [Fact]
    public void TypesNameTheirSchemaType()
    {
        IType[] types =
        [
            .. Records
                .Where(type => typeof(IType).IsAssignableFrom(type))
                .Select(type => (IType)Activator.CreateInstance(type)!),
        ];
        Assert.Equal(24, types.Length);
        foreach (IType type in types)
        {
            string declared = type.GetType().Name["Type".Length..];
            string name = declared.Replace("Nullable", "", StringComparison.Ordinal);
            Assert.Equal(char.ToLowerInvariant(name[0]) + name[1..], type.Name);
            Assert.Equal(
                declared.EndsWith("Nullable", StringComparison.Ordinal),
                type.Nullable
            );
        }
    }

    [Fact]
    public void EveryTypedRecordImplementsATypedInterface()
    {
        foreach (Type record in Records.Where(r => r.GetProperty("Type") is not null))
        {
            if (typeof(IType).IsAssignableFrom(record))
            {
                continue;
            }
            Assert.Contains(TypedInterfaces, i => i.IsAssignableFrom(record));
        }
    }

    [Fact]
    public void LeavesDeclareTheTypeInTheirName()
    {
        Type[] leaves =
        [
            .. Records.Where(type =>
                TypedInterfaces.Skip(1).Any(i => i.IsAssignableFrom(type))
            ),
        ];
        // Fields, parameters, literals, keys and subquery columns of every type, and the
        // literal and parameter lists of every non-null type.
        Assert.Equal((5 * 16) + (2 * 8), leaves.Length);
        foreach (Type leaf in leaves)
        {
            IType type = (IType)leaf.GetProperty("Type")!.GetValue(Sample(leaf))!;
            string declared = type.GetType()
                .Name["Type".Length..]
                .Replace("List", "", StringComparison.Ordinal);
            Assert.True(
                leaf.Name.EndsWith(declared, StringComparison.Ordinal),
                $"{leaf.Name} declares {type.GetType().Name}"
            );
        }
    }

    private static readonly string[] Operators =
    [
        "add",
        "subtract",
        "multiply",
        "divide",
        "integerDivide",
        "modulo",
        "floor",
        "ceiling",
        "round",
        "concat",
        "dateAddDays",
        "dateDiffDays",
        "timeAddSeconds",
        "timeDiffSeconds",
        "datetimeAddSeconds",
        "datetimeDiffSeconds",
        "and",
        "or",
        "not",
        "equal",
        "notEqual",
        "in",
        "greaterThan",
        "lessThan",
        "greaterThanOrEqual",
        "lessThanOrEqual",
        "if",
        "coalesce",
        "count",
        "sum",
        "average",
        "min",
        "max",
        "any",
        "all",
    ];

    private static readonly string[] Predicates =
    [
        "equal",
        "notEqual",
        "in",
        "greaterThan",
        "lessThan",
        "greaterThanOrEqual",
        "lessThanOrEqual",
    ];

    // `DecimalNullable` → `decimal?`
    private static string TypeOfToken(string token)
    {
        string name = token.Replace("Nullable", "", StringComparison.Ordinal);
        string type = char.ToLowerInvariant(name[0]) + name[1..];
        Assert.Contains(type, TypeNames);
        return type + (token.EndsWith("Nullable", StringComparison.Ordinal) ? "?" : "");
    }

    [Fact]
    public void OperatorsDeclareTheTypeInTheirName()
    {
        Type[] operators = [.. Records.Where(typeof(IOperator).IsAssignableFrom)];
        Assert.NotEmpty(operators);
        foreach (Type node in operators)
        {
            string context = Assert.Single(
                Contexts,
                c => node.Name.EndsWith(c, StringComparison.Ordinal)
            );
            string name = node.Name[..^context.Length];
            string op = Operators
                .Where(o =>
                    name.StartsWith(
                        char.ToUpperInvariant(o[0]) + o[1..],
                        StringComparison.Ordinal
                    )
                )
                .MaxBy(o => o.Length)!;
            Assert.NotNull(op);
            string token = name[op.Length..];
            string expected = op switch
            {
                "and" or "or" or "not" or "any" or "all" when token.Length == 0 =>
                    "boolean",
                "count" when token.Length == 0 => "integer",
                _ when Predicates.Contains(op) => "boolean",
                _ => TypeOfToken(token),
            };
            if (Predicates.Contains(op))
            {
                // `EqualDecimalRow` compares decimals.
                _ = TypeOfToken(token);
            }
            Assert.True(
                expected == Declared(node),
                $"{node.Name} declares {Declared(node)}, not {expected}"
            );
        }
    }

    [GeneratedRegex(
        "^(Integer|Decimal|String|Boolean|Date|Time|Datetime|Uuid)(Nullable)?"
            + "(Row|Projection|Group|Total)$"
    )]
    private static partial Regex Position();

    // The declared types each kind of expression union accepts.
    private static string[]? Accepted(Type union)
    {
        Match position = Position().Match(union.Name);
        if (position.Success)
        {
            string name = position.Groups[1].Value.ToLowerInvariant();
            bool nullable = position.Groups[2].Success;
            // A position takes its type, its nullable type if it is nullable, and an
            // integer where it takes a decimal.
            string[] names = name == "decimal" ? [name, "integer"] : [name];
            return [.. names.SelectMany(n => nullable ? new[] { n, n + "?" } : [n])];
        }
        string? context = Contexts.FirstOrDefault(c =>
            union.Name.EndsWith(c, StringComparison.Ordinal)
        );
        if (context is null || union.Namespace == typeof(PureQLQuery).Namespace)
        {
            return null;
        }
        string rest = union.Name[..^context.Length];
        if (rest == "Expr")
        {
            return [.. TypeNames.SelectMany(n => new[] { n, n + "?" })];
        }
        // `DeclaresDecimalRow`: exactly decimal; `IntegerNullableOrDecimalNullableRow`.
        string tokens = rest.StartsWith("Declares", StringComparison.Ordinal)
            ? rest["Declares".Length..]
            : rest;
        return [.. tokens.Split("Or").Select(TypeOfToken)];
    }

    [Fact]
    public void ExpressionUnionsHoldEveryExpressionTheyAccept()
    {
        Assert.Equal(4 * 16, Unions.Count(u => Position().IsMatch(u.Name)));
        Type[] unions = [.. Unions.Where(u => Accepted(u) is not null)];
        foreach (Type union in unions)
        {
            string context = Contexts.Single(c =>
                union.Name.EndsWith(c, StringComparison.Ordinal)
            );
            Type expressions = Unions.Single(u => u.Name == "Expr" + context);
            string[] accepted = Accepted(union)!;
            Assert.Equal(
                Cases(expressions)
                    .Where(e => accepted.Contains(Declared(e)))
                    .Select(e => e.Name)
                    .Order(StringComparer.Ordinal),
                Cases(union).Select(e => e.Name).Order(StringComparer.Ordinal)
            );
        }
        // Each context's expressions declare every type of the schema.
        foreach (string context in Contexts)
        {
            Type expressions = Unions.Single(u => u.Name == "Expr" + context);
            Assert.Equal(
                TypeNames.SelectMany(n => new[] { n, n + "?" }).Order(),
                Cases(expressions).Select(Declared).Distinct().Order()
            );
        }
    }

    [Fact]
    public void SubqueryColumnsDeclareTheirNullability()
    {
        Type[] columns = [.. Records.Where(typeof(ISubqueryColumn).IsAssignableFrom)];
        Assert.Equal(16, columns.Length);
        foreach (Type column in columns)
        {
            ISubqueryColumn instance = (ISubqueryColumn)
                Activator.CreateInstance(column, "totals", "total")!;
            Assert.Equal("totals", instance.Subquery);
            Assert.Equal("total", instance.Field);
            Assert.Equal(
                column.Name.EndsWith("Nullable", StringComparison.Ordinal),
                instance.Type.Nullable
            );
            Assert.Equal("ListSubqueryColumn" + TypeToken(instance.Type), column.Name);
        }
    }

    private static string TypeToken(IType type)
    {
        return char.ToUpperInvariant(type.Name[0])
            + type.Name[1..]
            + (type.Nullable ? "Nullable" : "");
    }
}
